  ('20261019120000_7c2e4a10-contracts.sql', CASE WHEN NOT to_regclass('public.contracts') IS NOT NULL THEN 'table contracts' WHEN NOT to_regclass('public.contract_parties') IS NOT NULL THEN 'table contract_parties' WHEN NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'freeze_sent_contract' AND pronamespace = 'public'::regnamespace) THEN 'function freeze_sent_contract' WHEN NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'freeze_sent_contract' AND pronamespace = 'public'::regnamespace AND prosrc LIKE '%OR NEW.title IS DISTINCT FROM OLD.title OR NEW.blueprint IS DISTINCT FROM OLD.blueprint OR NEW.catalog_id IS DISTINCT FROM OLD.catalog_id) THEN%') THEN 'newest version of freeze_sent_contract' WHEN NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'freeze_sent_contract_parties' AND pronamespace = 'public'::regnamespace) THEN 'function freeze_sent_contract_parties' WHEN NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'freeze_sent_contract_parties' AND pronamespace = 'public'::regnamespace AND prosrc LIKE '%AND NEW.position = OLD.position AND NEW.signed_at IS NOT DISTINCT FROM OLD.signed_at THEN RETURN NEW; END IF;%') THEN 'newest version of freeze_sent_contract_parties' WHEN NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'send_contract' AND pronamespace = 'public'::regnamespace) THEN 'function send_contract' WHEN NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'reopen_contract' AND pronamespace = 'public'::regnamespace) THEN 'function reopen_contract' WHEN NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'get_contract_invite' AND pronamespace = 'public'::regnamespace) THEN 'function get_contract_invite' WHEN NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'get_contract_invite' AND pronamespace = 'public'::regnamespace AND prosrc LIKE '%SELECT * INTO p FROM contract_parties WHERE id = _party_id;%') THEN 'newest version of get_contract_invite' WHEN NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'sign_contract' AND pronamespace = 'public'::regnamespace) THEN 'function sign_contract' WHEN NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'sign_contract' AND pronamespace = 'public'::regnamespace AND prosrc LIKE '%IF NOT EXISTS (SELECT 1 FROM contract_parties WHERE contract_id = k.id AND signed_at IS NULL) THEN%') THEN 'newest version of sign_contract' WHEN NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'my_contract_invites' AND pronamespace = 'public'::regnamespace) THEN 'function my_contract_invites' WHEN NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'my_contract_invites' AND pronamespace = 'public'::regnamespace AND prosrc LIKE '%SELECT p.id, k.title, p.role, k.status, p.signed_at, k.sent_at, k.completed_at%') THEN 'newest version of my_contract_invites' WHEN NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'contracts' AND policyname = 'Owners manage own contracts') THEN 'policy Owners manage own contracts' WHEN NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'contract_parties' AND policyname = 'Owners manage parties of own contracts') THEN 'policy Owners manage parties of own contracts' WHEN NOT coalesce(has_function_privilege('authenticated', to_regprocedure('public.reopen_contract(uuid)'), 'EXECUTE'), false) THEN 'reopen_contract callable by authenticated' WHEN NOT coalesce(has_function_privilege('authenticated', to_regprocedure('public.get_contract_invite(uuid)'), 'EXECUTE'), false) THEN 'get_contract_invite callable by authenticated' WHEN NOT coalesce(has_function_privilege('authenticated', to_regprocedure('public.sign_contract(uuid, text)'), 'EXECUTE'), false) THEN 'sign_contract callable by authenticated' WHEN NOT coalesce(has_function_privilege('authenticated', to_regprocedure('public.my_contract_invites()'), 'EXECUTE'), false) THEN 'my_contract_invites callable by authenticated' ELSE NULL END, '20 checks'),
