  ('20261020130000_d6b1f3a8-security-linter-fixes.sql', CASE WHEN NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'admin_whitelist' AND policyname = 'Staff managers manage the whitelist') THEN 'policy Staff managers manage the whitelist' WHEN NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'royalty_health_checks' AND policyname = 'Owners read their health checks') THEN 'policy Owners read their health checks' WHEN NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'royalty_health_checks' AND policyname = 'Staff manage health checks') THEN 'policy Staff manage health checks' WHEN NOT (to_regprocedure('public.has_role(uuid, public.user_role)') IS NOT NULL AND NOT coalesce(has_function_privilege('anon', to_regprocedure('public.has_role(uuid, public.user_role)'), 'EXECUTE'), false)) THEN 'has_role blocked for anon' WHEN NOT (to_regprocedure('public.is_staff(uuid)') IS NOT NULL AND NOT coalesce(has_function_privilege('anon', to_regprocedure('public.is_staff(uuid)'), 'EXECUTE'), false)) THEN 'is_staff blocked for anon' WHEN NOT (to_regprocedure('public.can_manage_staff(uuid)') IS NOT NULL AND NOT coalesce(has_function_privilege('anon', to_regprocedure('public.can_manage_staff(uuid)'), 'EXECUTE'), false)) THEN 'can_manage_staff blocked for anon' WHEN NOT (to_regprocedure('public.in_department(uuid, text)') IS NOT NULL AND NOT coalesce(has_function_privilege('anon', to_regprocedure('public.in_department(uuid, text)'), 'EXECUTE'), false)) THEN 'in_department blocked for anon' WHEN NOT (to_regprocedure('public.is_room_host(uuid, uuid)') IS NOT NULL AND NOT coalesce(has_function_privilege('anon', to_regprocedure('public.is_room_host(uuid, uuid)'), 'EXECUTE'), false)) THEN 'is_room_host blocked for anon' WHEN NOT (to_regprocedure('public.is_room_member(uuid, uuid)') IS NOT NULL AND NOT coalesce(has_function_privilege('anon', to_regprocedure('public.is_room_member(uuid, uuid)'), 'E