  ('20261020140000_f2c7a9d4-invite-send-log-and-blocklist.sql', CASE WHEN NOT to_regclass('public.invite_sends') IS NOT NULL THEN 'table invite_sends' WHEN NOT to_regclass('public.invite_blocklist') IS NOT NULL THEN 'table invite_blocklist' WHEN NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'invite_sends' AND policyname = 'Staff read invite sends') THEN 'policy Staff read invite sends' WHEN NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'invite_blocklist' AND policyname = 'Staff read the invite blocklist') THEN 'policy Staff read the invite blocklist' WHEN NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'invite_blocklist' AND policyname = 'Staff remove invite blocklist entries') THEN 'policy Staff remove invite blocklist entries' WHEN NOT coalesce(has_table_privilege('service_role', to_regclass('public.invite_sends'), 'SELECT'), false) THEN 'SELECT grant on invite_sends to service_role' WHEN NOT coalesce(has_table_privilege('authenticated', to_regclass('public.invite_sends'), 'SELECT'), false) THEN 'SELECT grant on invite_sends to authenticated' WHEN NOT coalesce(has_table_privilege('service_role', to_regclass('public.invite_blocklist'), 'SELECT'), false) THEN 'SELECT grant on invite_blocklist to service_role' WHEN NOT coalesce(has_table_privilege('authenticated', to_regclass('public.invite_blocklist'), 'SELECT'), false) THEN 'SELECT grant on invite_blocklist to authenticated' ELSE NULL END, '9 checks'),
