  ('20261022090000_d5b8f3c1-badge-log-and-drops.sql', CASE WHEN NOT to_regclass('public.badge_drops') IS NOT NULL THEN 'table badge_drops' WHEN NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'user_badges' AND column_name = 'log') THEN 'column user_badges.log' WHEN NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'badge_drops' AND policyname = 'Badge staff read badge drops') THEN 'policy Badge staff read badge drops' WHEN NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'badge_drops' AND policyname = 'Badge staff log badge drops') THEN 'policy Badge staff log badge drops' WHEN NOT coalesce(has_table_privilege('authenticated', to_regclass('public.badge_drops'), 'SELECT'), false) THEN 'SELECT grant on badge_drops to authenticated' WHEN NOT coalesce(has_table_privilege('service_role', to_regclass('public.badge_drops'), 'SELECT'), false) THEN 'SELECT grant on badge_drops to service_role' ELSE NULL END, '6 checks'),
  ('20261022100000_e7c2a4b6-new-departments.sql', CASE WHEN NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'user_roles_departments_valid' AND pg_get_constraintdef(oid) LIKE '%security%') THEN 'constraint user_roles_departments_valid' WHEN NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'department_tasks_department_check' AND pg_get_constraintdef(oid) LIKE '%security%') THEN 'constraint department_tasks_department_check' WHEN NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'can_manage_badges' AND pronamespace = 'public'::regnamespace) THEN 'function can_manage_badges' WHEN NOT coalesce(has_function_privilege('authenticated', to_regprocedure('public.can_manage_badges(uuid)'), 'EXECUTE'), false) THEN 'can_manage_badges callable by authenticated' WHEN NOT coalesce(has_function_privilege('service_role', to_regprocedure('public.can_manage_badges(uuid)'), 'EXECUTE'), false) THEN 'can_manage_badges callable by service_role' ELSE NULL END, '5 checks'),
  ('20261022110000_f1a9c3d7-support-badge-grants-and-task-bank.sql', CASE WHEN NOT to_regclass('public.badge_grants') IS NOT NULL THEN 'table badge_grants' WHEN NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'user_id_by_email' AND pronamespace = 'public'::regnamespace) THEN 'function user_id_by_email' WHEN NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'user_id_by_email' AND pronamespace = 'public'::regnamespace AND prosrc LIKE '%SELECT id FROM auth.users WHERE lower(email) = lower(trim(_email)) LIMIT 1%') THEN 'newest version of user_id_by_email' WHEN NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'badge_grants' AND policyname = 'Support reads badge grants') THEN 'policy Support reads badge grants' WHEN NOT coalesce(has_table_privilege('authenticated', to_regclass('public.badge_grants'), 'SELECT'), false) THEN 'SELECT grant on badge_grants to authenticated' WHEN NOT coalesce(has_table_privilege('service_role', to_regclass('public.badge_grants'), 'SELECT'), false) THEN 'SELECT grant on badge_grants to service_role' WHEN NOT coalesce(has_function_privilege('service_role', to_regprocedure('public.user_id_by_email(text)'), 'EXECUTE'), false) THEN 'user_id_by_email callable by service_role' ELSE NULL END, '7 checks'),
  ('20261022120000_a3d6e8f2-company-plans.sql', CASE WHEN NOT to_regclass('public.company_plans') IS NOT NULL THEN 'table company_plans' WHEN NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'company_plans' AND policyname = 'Super admins read plans') THEN 'policy Super admins read plans' WHEN NOT coalesce(has_table_privilege('authenticated', to_regclass('public.company_plans'), 'SELECT'), false) THEN 'SELECT grant on company_plans to authenticated' WHEN NOT coalesce(has_table_privilege('service_role', to_regclass('public.company_plans'), 'SELECT'), false) THEN 'SELECT grant on company_plans to service_role' ELSE NULL END, '4 checks'),
  ('20261022130000_b8e1d4a2-masterclass-interest.sql', CASE WHEN NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'feature_interest_feature_check' AND pg_get_constraintdef(oid) LIKE '%masterclasses%') THEN 'constraint feature_interest_feature_check' ELSE NULL END, '1 checks'),
  ('20261022140000_c5a9e3f1-ai-certificate-credits.sql', CASE WHEN NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'ai_protection_certificates' AND column_name = 'manifest') THEN 'column ai_protection_certificates.manifest' WHEN NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'can_issue_ai_certificate' AND pronamespace = 'public'::regnamespace) THEN 'function can_issue_ai_certificate' WHEN NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'ai_protection_certificates' AND policyname = 'Paid users issue own certificates') THEN 'policy Paid users issue own certificates' ELSE NULL END, '3 checks'),
  ('20261022150000_e2b7c9d4-catalog-lapses.sql', CASE WHEN NOT to_regclass('public.catalog_lapses') IS NOT NULL THEN 'table catalog_lapses' WHEN NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'split_sheets' AND column_name = 'track_title') THEN 'column split_sheets.track_title' WHEN NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'split_sheets' AND column_name = 'artist_name') THEN 'column split_sheets.artist_name' WHEN NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'split_sheets' AND column_name = 'isrc') THEN 'column split_sheets.isrc' WHEN NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'split_sheets' AND column_name = 'owner_id') THEN 'column split_sheets.owner_id' WHEN NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'snapshot_song_before_delete' AND pronamespace = 'public'::regnamespace) THEN 'function snapshot_song_before_delete' WHEN NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'snapshot_song_before_delete' AND pronamespace = 'public'::regnamespace AND prosrc LIKE '%UPDATE split_sheets SET track_title = OLD.track_title, artist_name = OLD.artist_name, isrc = OLD.isrc, owner_id = OLD.user_id%') THEN 'newest version of snapshot_song_before_delete' WHEN NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'get_split_invite' AND pronamespace = 'public'::regnamespace) THEN 'function get_split_invite' WHEN NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'get_split_invite' AND pronamespace = 'public'::regnamespace AND prosrc LIKE '%SELECT s.*, coalesce(c.track_title, s.track_title) AS song_title, coalesce(c.artist_name, s.artist_name) AS song_artist,%') THEN 'newest version of get_split_invite' WHEN NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'sign_split_invite' AND pronamespace = 'public'::regnamespace) THEN 'function sign_split_invite' WHEN NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'sign_split_invite' AND pronamespace = 'public'::regnamespace AND prosrc LIKE '%SELECT s.*, c.user_id AS owner_id INTO r FROM split_sheets s JOIN catalogs c ON c.id = s.catalog_id WHERE s.id = _row_id;%') THEN 'newest version of sign_split_invite' WHEN NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'catalog_lapse_candidates' AND pronamespace = 'public'::regnamespace) THEN 'function catalog_lapse_candidates' WHEN NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'catalog_lapses' AND policyname = 'Users see their own catalog lapse') THEN 'policy Users see their own catalog lapse' WHEN NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'split_sheets' AND policyname = 'Owners read split sheets of removed songs') THEN 'policy Owners read split sheets of removed songs' WHEN NOT coalesce(has_table_privilege('authenticated', to_regclass('public.catalog_lapses'), 'SELECT'), false) THEN 'SELECT grant on catalog_lapses to authenticated' WHEN NOT coalesce(has_table_privilege('service_role', to_regclass('public.catalog_lapses'), 'SELECT'), false) THEN 'SELECT grant on catalog_lapses to service_role' WHEN NOT (to_regprocedure('public.get_split_invite(uuid)') IS NOT NULL AND NOT coalesce(has_function_privilege('anon', to_regprocedure('public.get_split_invite(uuid)'), 'EXECUTE'), false)) THEN 'get_split_invite blocked for anon' WHEN NOT (to_regprocedure('public.sign_split_invite(uuid, text, text, text, text)') IS NOT NULL AND NOT coalesce(has_function_privilege('anon', to_regprocedure('public.sign_split_invite(uuid, text, text, text, text)'), 'EXECUTE'), false)) THEN 'sign_split_invite blocked for anon' ELSE NULL END, '18 checks'),
  ('20261022160000_f4a8d2c6-ai-single-songs.sql', CASE WHEN NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'can_issue_ai_certificate' AND pronamespace = 'public'::regnamespace) THEN 'function can_issue_ai_certificate' WHEN NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'can_issue_ai_certificate' AND pronamespace = 'public'::regnamespace AND prosrc LIKE '%> (SELECT count(*) FROM public.ai_protection_certificates WHERE user_id = _user_id);%') THEN 'newest version of can_issue_ai_certificate' WHEN NOT (to_regprocedure('public.can_issue_ai_certificate(uuid)') IS NOT NULL AND NOT coalesce(has_function_privilege('anon', to_regprocedure('public.can_issue_ai_certificate(uuid)'), 'EXECUTE'), false)) THEN 'can_issue_ai_certificate blocked for anon' WHEN NOT coalesce(has_function_privilege('authenticated', to_regprocedure('public.can_issue_ai_certificate(uuid)'), 'EXECUTE'), false) THEN 'can_issue_ai_certificate callable by authenticated' ELSE NULL END, '4 checks'),
  ('20261022170000_a7c3e5f9-company-contracts.sql', CASE WHEN NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'contracts' AND column_name = 'is_company') THEN 'column contracts.is_company' WHEN NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'contracts' AND policyname = 'Only super admins create company contracts') THEN 'policy Only super admins create company contracts' ELSE NULL END, '2 checks'),
  ('20261023090000_b3d6f1a8-registration-intake.sql', CASE WHEN NOT to_regclass('public.registration_orders') IS NOT NULL THEN 'table registration_orders' WHEN NOT to_regclass('public.registration_songs') IS NOT NULL THEN 'table registration_songs' WHEN NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'registration_orders' AND policyname = 'Users read own registration orders') THEN 'policy Users read own registration orders' WHEN NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'registration_songs' AND policyname = 'Users read own registration songs') THEN 'policy Users read own registration songs' WHEN NOT coalesce(has_table_privilege('authenticated', to_regclass('public.registration_orders'), 'SELECT'), false) THEN 'SELECT grant on registration_orders to authenticated' WHEN NOT coalesce(has_table_privilege('authenticated', to_regclass('public.registration_songs'), 'SELECT'), false) THEN 'SELECT grant on registration_songs to authenticated' WHEN NOT coalesce(has_table_privilege('service_role', to_regclass('public.registration_orders'), 'SELECT'), false) THEN 'SELECT grant on registration_orders to service_role' WHEN NOT coalesce(has_table_privilege('service_role', to_regclass('public.registration_songs'), 'SELECT'), false) THEN 'SELECT grant on registration_songs to service_role' ELSE NULL END, '8 checks'),
  ('20261024090000_c5e9a3b7-account-pauses.sql', CASE WHEN NOT to_regclass('public.account_pauses') IS NOT NULL THEN 'table account_pauses' WHEN NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'is_paused' AND pronamespace = 'public'::regnamespace) THEN 'function is_paused' WHEN NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'is_paused' AND pronamespace = 'public'::regnamespace AND prosrc LIKE '%SELECT 1 FROM account_pauses p%') THEN 'newest version of is_paused' WHEN NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'user_tier' AND pronamespace = 'public'::regnamespace) THEN 'function user_tier' WHEN NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'user_tier' AND pronamespace = 'public'::regnamespace AND prosrc LIKE '%AND (NOT EXISTS (SELECT 1 FROM env) OR s.environment = (SELECT e FROM env))%') THEN 'newest version of user_tier' WHEN NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'catalog_lapse_candidates' AND pronamespace = 'public'::regnamespace) THEN 'function catalog_lapse_candidates' WHEN NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'catalog_lapse_candidates' AND pronamespace = 'public'::regnamespace AND prosrc LIKE '%JOIN subscriptions s ON s.user_id = o.user_id AND (NOT EXISTS (SELECT 1 FROM env) OR s.environment = (SELECT e FROM env))%') THEN 'newest version of catalog_lapse_candidates' WHEN NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'account_pauses' AND policyname = 'Users see their own pauses') THEN 'policy Users see their own pauses' WHEN NOT coalesce(has_table_privilege('authenticated', to_regclass('public.account_pauses'), 'SELECT'), false) THEN 'SELECT grant on account_pauses to authenticated' WHEN NOT coalesce(has_table_privilege('service_role', to_regclass('public.account_pauses'), 'SELECT'), false) THEN 'SELECT grant on account_pauses to service_role' WHEN NOT coalesce(has_table_privilege('service_role', to_regclass('public.catalog_lapses'), 'SELECT'), false) THEN 'SELECT grant on catalog_lapses to service_role' WHEN NOT coalesce(has_function_privilege('authenticated', to_regprocedure('public.is_paused(uuid)'), 'EXECUTE'), false) THEN 'is_paused callable by authenticated' WHEN NOT coalesce(has_function_privilege('service_role', to_regprocedure('public.is_paused(uuid)'), 'EXECUTE'), false) THEN 'is_paused callable by service_role' WHEN NOT coalesce(has_function_privilege('authenticated', to_regprocedure('public.user_tier(uuid)'), 'EXECUTE'), false) THEN 'user_tier callable by authenticated' WHEN NOT coalesce(has_function_privilege('service_role', to_regprocedure('public.user_tier(uuid)'), 'EXECUTE'), false) THEN 'user_tier callable by service_role' WHEN NOT coalesce(has_function_privilege('service_role', to_regprocedure('public.catalog_lapse_candidates()'), 'EXECUTE'), false) THEN 'catalog_lapse_candidates callable by service_role' ELSE NULL END, '16 checks'),
  ('20261024100000_d7f1b4e2-renewal-reminders.sql', CASE WHEN NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'subscriptions' AND column_name = 'renewal_reminders') THEN 'column subscriptions.renewal_reminders' WHEN NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'subscriptions' AND column_name = 'renewal_reminders_for') THEN 'column subscriptions.renewal_reminders_for' ELSE NULL END, '2 checks'),
  ('20261024110000_e2a8c6f1-contracts-grants.sql', CASE WHEN NOT coalesce(has_table_privilege('authenticated', to_regclass('public.contracts'), 'SELECT'), false) THEN 'SELECT grant on contracts to authenticated' WHEN NOT coalesce(has_table_privilege('authenticated', to_regclass('public.contract_parties'), 'SELECT'), false) THEN 'SELECT grant on contract_parties to authenticated' WHEN NOT coalesce(has_table_privilege('service_role', to_regclass('public.contracts'), 'SELECT'), false) THEN 'SELECT grant on contracts to service_role' WHEN NOT coalesce(has_table_privilege('service_role', to_regclass('public.contract_parties'), 'SELECT'), false) THEN 'SELECT grant on contract_parties to service_role' ELSE NULL END, '4 checks'),
  ('20261024120000_b9d3f7a2-company-sign-by-link.sql', CASE WHEN NOT to_regclass('public.contract_sign_codes') IS NOT NULL THEN 'table contract_sign_codes' WHEN NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'contract_parties' AND column_name = 'consent_at') THEN 'column contract_parties.consent_at' WHEN NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'contract_parties' AND column_name = 'ip_hash') THEN 'column contract_parties.ip_hash' WHEN NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'contract_parties' AND column_name = 'user_agent') THEN 'column contract_parties.user_agent' WHEN NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'sign_contract_by_link' AND pronamespace = 'public'::regnamespace) THEN 'function sign_contract_by_link' WHEN NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'sign_contract_by_link' AND pronamespace = 'public'::regnamespace AND prosrc LIKE '%IF NOT EXISTS (SELECT 1 FROM contract_parties WHERE contract_id = k.id AND signed_at IS NULL) THEN%') THEN 'newest version of sign_contract_by_link' WHEN NOT coalesce(has_table_privilege('service_role', to_regclass('public.contract_sign_codes'), 'SELECT'), false) THEN 'SELECT grant on contract_sign_codes to service_role' WHEN NOT coalesce(has_function_privilege('service_role', to_regprocedure('public.sign_contract_by_link(uuid, text, text, text)'), 'EXECUTE'), false) THEN 'sign_contract_by_link callable by service_role' ELSE NULL END, '8 checks'),
  ('20261024130000_f4b8d2e6-royalty-health-reports.sql', CASE WHEN NOT to_regclass('public.royalty_health_reports') IS NOT NULL THEN 'table royalty_health_reports' WHEN NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'royalty_health_reports_trim' AND pronamespace = 'public'::regnamespace) THEN 'function royalty_health_reports_trim' WHEN NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'royalty_health_reports_trim' AND pronamespace = 'public'::regnamespace AND prosrc LIKE '%SELECT id FROM public.royalty_health_reports WHERE user_id = NEW.user_id ORDER BY created_at DESC OFFSET 100);%') THEN 'newest version of royalty_health_reports_trim' WHEN NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'royalty_health_reports' AND policyname = 'Users manage own health reports') THEN 'policy Users manage own health reports' WHEN NOT coalesce(has_table_privilege('authenticated', to_regclass('public.royalty_health_reports'), 'SELECT'), false) THEN 'SELECT grant on royalty_health_reports to authenticated' WHEN NOT coalesce(has_table_privilege('service_role', to_regclass('public.royalty_health_reports'), 'SELECT'), false) THEN 'SELECT grant on royalty_health_reports to service_role' ELSE NULL END, '6 checks')
) AS m(migration, missing, note)
ORDER BY (missing IS NULL), migration;
